'use strict';
const assert=require('node:assert/strict'),crypto=require('node:crypto'),fs=require('node:fs'),path=require('node:path'),M=require('../model.js'),{fixture}=require('./dom_fixture.cjs');
const root=path.resolve(__dirname,'..'),read=f=>JSON.parse(fs.readFileSync(path.join(root,'data',f),'utf8'));
const model=M.buildModel(read('catalog.json'),read('literature-seed.json'),read('challenge-seed.json'));let count=0;function test(name,fn){fn();count++;console.log('PASS '+name);}
const allPaths=['l','c'].flatMap(k=>model.trees[k].paths.map(p=>({...p,key:k})));const go=(s,a)=>M.reduce(model,s,a);
test('canonical input is unchanged from the independently source-verified frozen projection',()=>{const src=fs.readFileSync(path.join(root,'data/catalog.json'));assert.equal(crypto.createHash('sha256').update(src).digest('hex'),fs.readFileSync(path.join(root,'data/catalog-SHA256.txt'),'utf8').trim());assert.equal(model.catalog.source_sha256,'349c19f327db19a16d0d493f83d603f3c7b94ca35ab4815edb32f2e0c20b25b3');});
test('canonical corpus is preserved, independently searchable, and validates',()=>{assert.equal(model.papers.size,39);assert.equal(M.catalogResults(model).length,39);assert.deepEqual(M.validate(model),[]);assert.equal(new Set([...model.papers.values()].map(p=>p.canonical_id)).size,39);});
test('coverage counts unique paper identities rather than paths or rendered nodes',()=>{const c=M.coverage(model);for(const [key,name]of [['l','literature'],['c','challenge']])assert.equal(c[name],new Set(model.trees[key].paths.map(p=>p.paperId)).size);assert.equal(c.catalog,39);});
test('every path supports layer-by-layer navigation to exactly its canonical paper',()=>{for(const p of allPaths){let s=M.initialState();if(p.key==='l'&&p.viewKind!=='protocol')s=go(s,{type:'facet',facet:p.viewKind});for(const id of p.nodeIds)s=go(s,{type:'enter',key:p.key,id});assert.equal(s.paper,p.paperId,p.id);assert.deepEqual(s.origin.path,p.nodeIds);}});
test('a layer has bounded cards and explicit pages cover all children without truncation',()=>{for(const key of ['l','c']){const prefixes=[[],...model.trees[key].paths.flatMap(p=>p.nodeIds.map((_,i)=>p.nodeIds.slice(0,i+1)))];for(const prefix of prefixes){let s=M.initialState();s[key]=prefix;if(key==='l'&&prefix.length>1){const p=model.trees.l.paths.find(p=>M.startsWith(p.nodeIds,prefix));if(p&&p.viewKind!=='protocol')s.lFacet=p.viewKind;}const b=M.branch(model,s,key),ids=[];for(let page=0;page<=b.maxPage;page++){s=go(s,{type:'page',key,page});const visible=M.branch(model,s,key);assert(visible.items.length<=M.PAGE_SIZE);ids.push(...visible.items.map(x=>x.node.id));}assert.deepEqual(ids,b.all.map(x=>x.node.id));}}});
test('returning to parent restores its page rather than jumping to first four',()=>{const key=['l','c'].find(k=>M.children(model.trees[k]).length>M.PAGE_SIZE);assert(key);let s=go(M.initialState(),{type:'page',key,page:1});const n=M.branch(model,s,key).items[0].node;s=go(s,{type:'enter',key,id:n.id});s=go(s,{type:'back',key});assert.equal(s.pages[key],1);assert(M.branch(model,s,key).items.some(x=>x.node.id===n.id));});
test('multi-parent papers retain all valid paths without cross-task combinations',()=>{const paper=[...model.papers.keys()].find(id=>M.pathsForPaper(model,id).filter(p=>p.key==='l').length>1);assert(paper);const paths=M.pathsForPaper(model,paper).filter(p=>p.key==='l');for(const p of paths){let s=go(M.initialState(),{type:'path',key:'l',id:p.id});assert.equal(s.paper,paper);assert.deepEqual(s.l,p.nodeIds.slice(0,-1));assert(M.branch(model,s,'l').items.some(x=>x.node.type==='paper_ref'&&x.node.paper_id===paper));}});
test('forbidden sibling from another root cannot be entered into a valid prefix',()=>{const a=allPaths.find(p=>p.key==='l'&&p.nodeIds.length>3),other=allPaths.find(p=>p.key==='l'&&p.nodeIds[0]!==a.nodeIds[0]&&p.nodeIds.length>3);assert(a&&other);let s=go(M.initialState(),{type:'enter',key:'l',id:a.nodeIds[0]});const next=go(s,{type:'enter',key:'l',id:other.nodeIds[1]});assert.strictEqual(next,s);});
test('stable path IDs survive input reordering',()=>{const raw=read('literature-seed.json'),original=M.normalizeLiterature(raw);raw.paths.reverse();const reversed=M.normalizeLiterature(raw);assert.deepEqual(new Set(original.paths.map(p=>p.id)),new Set(reversed.paths.map(p=>p.id)));});
test('search includes source evidence and returns no fabricated result',()=>{for(const p of model.papers.values())assert(M.catalogResults(model,p.canonical_id).some(x=>x.canonical_id===p.canonical_id));assert.equal(M.catalogResults(model,'__no_such_paper_492765__').length,0);});
test('search excluding selection clears stale evidence; clearing recovers all papers',()=>{let s=go(M.initialState(),{type:'paper',id:[...model.papers.keys()][0]});s=go(s,{type:'search',query:'__no_such_paper_492765__'});assert.equal(s.paper,null);s=go(s,{type:'clearSearch'});assert.equal(M.catalogResults(model,s.query).length,39);});
test('history state round trip preserves paths, pages, selection and search',()=>{const p=allPaths.find(x=>x.key==='l');let s=go(M.initialState(),{type:'path',key:p.key,id:p.id});s=go(s,{type:'tab',tab:'paths'});assert.deepEqual(M.deserialize(model,M.serialize(s)),s);});
test('malformed URL state cannot create a fake path or crash an unknown origin',()=>{const s=M.sanitizeState(model,{paper:[...model.papers.keys()][0],l:['fake'],c:['fake'],origin:{key:'fake',path:[]}});assert.deepEqual(s.l,[]);assert.deepEqual(s.c,[]);assert.equal(s.origin,null);});
test('script-free alternative includes every canonical record and original evidence',()=>{const html=fs.readFileSync(path.join(root,'all-papers.html'),'utf8');assert.equal((html.match(/<article id="paper-/g)||[]).length,39);for(const p of model.papers.values()){assert(html.includes('id="paper-'+p.canonical_id+'"'));assert(html.includes(p.short_name));assert(html.includes(p.source_url.replace(/&/g,'&amp;')));}assert(!/<script\b/.test(html));});
test('DOM initial scope counts corpus and exposes three task families and all challenge roots',()=>{const f=fixture();assert.deepEqual(f.errors,[]);assert(f.app);assert(f.$('#coverage').textContent.includes('总收录 39'));for(const key of ['l','c'])assert.equal(f.$('#tree-'+key).hidden,key!=='l');const panel=f.$('#global-panel-l'),groups=panel.querySelectorAll('.task-family');assert.equal(groups.length,3);assert.deepEqual(groups.map(el=>el.dataset.id),M.taskMap.groups.map(g=>g.id));for(const el of groups){assert.equal(el.tagName,'BUTTON');assert.equal(el.getAttribute('aria-pressed'),'false');}assert.equal(panel.querySelectorAll('.protocol-card').length,0);assert(f.$('#global-panel-c').querySelector('.atlas-svg'));assert.equal(f.$('#global-panel-c').querySelectorAll('.atlas-root').length,M.rootOverview(model,'c').length);});
test('DOM all 39 records open four tabs without undefined placeholders or scope promotion',()=>{const f=fixture();for(const p of model.papers.values()){f.app.dispatch({type:'paper',id:p.canonical_id});for(const tab of ['evidence','overview','paths','analysis']){f.app.dispatch({type:'tab',tab});assert(!f.$('#paper-panel').textContent.includes('undefined'),p.canonical_id+' '+tab);assert(f.$('#paper-panel').innerHTML.includes('https://'));}assert(!f.$('#paper-panel').textContent.includes('全文精读完成'));}});
test('DOM switching paper and switching tab reset long evidence body to top',()=>{const f=fixture(),ids=[...model.papers.keys()];f.app.dispatch({type:'paper',id:ids[0]});f.$('#paper-body').scrollTop=467;f.app.dispatch({type:'paper',id:ids[1]});assert.equal(f.$('#paper-body').scrollTop,0);f.$('#paper-body').scrollTop=375;f.app.dispatch({type:'tab',tab:'overview'});assert.equal(f.$('#paper-body').scrollTop,0);});
test('DOM navigation preserves other tree scope and uses one shared paper panel',()=>{const f=fixture(),p=allPaths.find(x=>x.key==='l');f.app.dispatch({type:'path',key:'l',id:p.id});const old=[...f.app.getState().l],q=allPaths.find(x=>x.key==='c');f.app.dispatch({type:'path',key:'c',id:q.id});assert.deepEqual([...f.app.getState().l],old);assert.equal(f.$$('#paper-panel').length,1);assert.equal(f.$('#paper-title').textContent,model.papers.get(q.paperId).short_name);});
test('DOM back and forward restore selected canonical and legitimate path',()=>{const f=fixture(),p=allPaths.find(x=>x.key==='l'),q=allPaths.find(x=>x.key==='c');f.app.dispatch({type:'path',key:'l',id:p.id});const before=JSON.stringify(f.app.getState());f.app.dispatch({type:'path',key:'c',id:q.id});f.back();assert.equal(JSON.stringify(f.app.getState()),before);f.forward();assert.equal(f.app.getState().paper,q.paperId);});
test('DOM challenge parent return restores page and current-layer scroll',()=>{const f=fixture(),key='c',root=M.rootOverview(model,key).find(x=>x.childCount>M.PAGE_SIZE);assert(root);f.app.dispatch({type:'root',key,id:root.node.id});f.app.dispatch({type:'page',key,page:1});f.$('#body-'+key).scrollTop=165;const n=M.branch(model,f.app.getState(),key).items[0].node;f.app.dispatch({type:'enter',key,id:n.id});f.app.dispatch({type:'back',key});assert.equal(f.app.getState().pages[key],1);assert.equal(f.$('#body-'+key).scrollTop,165);});
test('DOM literature native protocol directory reaches all original contracts',()=>{const f=fixture(),seen=new Set();for(const group of M.taskMap.groups){f.click('.task-family[data-id="'+group.id+'"]');assert.equal(f.app.getState().taskGroup,group.id);for(const id of group.sections.flatMap(s=>s.ids)){const el=f.$('.protocol-card[data-id="'+id+'"]');assert(el,id);assert.equal(el.tagName,'BUTTON');el.emit('click');assert.equal(f.app.getState().l[0],id);assert.equal(el.getAttribute('type'),'button');assert(f.$('#tree-l').querySelector('.protocol-summary'));seen.add(id);}}assert.equal(seen.size,M.rootOverview(model,'l').length);});
test('DOM keyboard tabs support arrows, Home/End and Escape closes paper',()=>{const f=fixture();f.app.dispatch({type:'paper',id:[...model.papers.keys()][0]});f.$('#tab-evidence').emit('keydown',{key:'ArrowRight'});assert.equal(f.app.getState().tab,'overview');f.$('#tab-overview').emit('keydown',{key:'End'});assert.equal(f.app.getState().tab,'analysis');f.$('#tab-analysis').emit('keydown',{key:'Home'});assert.equal(f.app.getState().tab,'evidence');f.$('#tab-evidence').emit('keydown',{key:'Escape'});assert.equal(f.app.getState().paper,null);});
test('DOM no-result/clear/overview are complete native controls',()=>{const f=fixture();f.$('#search').value='__no_such_paper_492765__';f.$('#search-form').emit('submit');assert(f.$('#catalog-panel').textContent.includes('搜索结果 0'));assert(f.$('#catalog-panel').textContent.includes('没有匹配结果'));f.click('[data-action="clearSearch"]');assert.equal(f.app.getState().query,'');assert(f.$('#catalog-panel').textContent.includes('搜索结果 39'));f.app.dispatch({type:'overview'});assert.equal(f.app.getState().view,'trees');assert.equal(f.app.getState().paper,null);});
test('DOM narrow-mode selection brings the evidence region into reading order',()=>{const f=fixture({mobile:true});f.app.dispatch({type:'paper',id:[...model.papers.keys()][0]});assert.equal(f.$('#paper-panel').hidden,false);assert.equal(f.document.activeElement.id,'paper-title');assert.equal(f.$('#paper-panel').scrollTop,0);});
test('readable C palette and detail text retained beside a bounded complete SVG',()=>{const css=fs.readFileSync(path.join(root,'style.css'),'utf8'),js=fs.readFileSync(path.join(root,'app.js'),'utf8');assert(css.includes('--accent:#bd442a'));assert(css.includes('--paper:#fbf9f4'));assert(css.includes('font-size:16px'));assert(!js.includes('scale('));assert(!js.includes('createElementNS'));assert(!js.includes('7320'));});
test('literature facet switch retains the selected task and separates pipeline from representation',()=>{const f=fixture(),task=M.children(model.trees.l).find(x=>x.paperIds.length>0).node.id;f.app.dispatch({type:'enter',key:'l',id:task});let items=M.branch(model,f.app.getState(),'l').all;assert(items.every(x=>['pipeline','protocol'].includes(x.node.type)));f.app.dispatch({type:'facet',facet:'representation'});assert.equal(f.app.getState().l[0],task);items=M.branch(model,f.app.getState(),'l').all;assert(items.every(x=>['representation','protocol'].includes(x.node.type)));assert.equal(f.$('[data-action="facet"][data-facet="representation"]').getAttribute('aria-pressed'),'true');assert(f.$('#tree-l').textContent.includes('看信息表示'));});
test('historical and unpopulated task contracts remain reachable as source references',()=>{const taskNodes=[...model.trees.l.nodes.values()].filter(n=>n.type==='task_contract');assert.equal(M.children(model.trees.l).length,taskNodes.length);for(const n of taskNodes){const s=go(M.initialState(),{type:'enter',key:'l',id:n.id});assert.equal(s.l[0],n.id);}});
test('supplementary primary checks are readable even when opening a paper from catalog',()=>{const f=fixture();f.app.dispatch({type:'paper',id:'3d-mem'});assert(f.$('#paper-body').textContent.includes('本轮结构核查补充'));assert(f.$('#paper-body').textContent.includes('global navmesh'));});
test('paper-analysis entry is an honest pending state, without invented reading hierarchy',()=>{const f=fixture();f.app.dispatch({type:'paper',id:[...model.papers.keys()].find(id=>id!=='harnessvln')});f.app.dispatch({type:'tab',tab:'analysis'});assert(f.$('#paper-body').textContent.includes('待建立'));assert(f.$('#paper-body').textContent.includes('不会复制HarnessVLN的答案'));});
test('typed implementation references resolve and retain GOAT-Bench baseline variants',()=>{for(const p of model.trees.l.paths)if(p.raw.implementation_variant_ref){assert(p.implementationVariant,p.id);assert.equal(p.implementationVariant.paper_id,p.paperId);}const p=model.trees.l.paths.find(p=>p.raw.implementation_variant_ref==='goat-bench::skill-chain');assert(p);const f=fixture();f.app.dispatch({type:'path',key:'l',id:p.id});f.app.dispatch({type:'tab',tab:'evidence'});assert(f.$('#paper-body').textContent.includes('SenseAct-NN Skill Chain'));assert(f.$('#paper-body').textContent.includes('基线实现/比较角色'));});
test('shared module does not replace per-paper implementation with invented inheritance',()=>{const shared=model.trees.l.raw.concept_catalog.find(c=>c.type==='module'&&c.shared_across_papers);assert(shared);const n=[...model.trees.l.nodes.values()].find(n=>n.concept_id===shared.concept_id);assert(n);const p=model.trees.l.paths.find(p=>p.nodeIds.includes(n.id));const f=fixture();f.app.dispatch({type:'path',key:'l',id:p.id});const detail=f.$('#tree-l').querySelector('.mechanism-detail');assert(detail);assert(detail.textContent.includes(n.label));assert(detail.textContent.includes(model.papers.get(p.paperId).short_name));assert(f.$('#tree-l').textContent.includes('不代表首创或先后继承'));assert.deepEqual([...f.app.getState().origin.path],p.nodeIds);});
console.log('\n'+count+' tests passed. Model and in-memory DOM only; actual browser rendering and responsive visual acceptance NOT RUN.');
fs.writeFileSync(path.join(root,'tests/report.json'),JSON.stringify({status:'passed',checks:count,coverage:M.coverage(model),scope:'Model and in-memory DOM contracts only',browser_rendering:'NOT_RUN',real_screenshots:'NOT_RUN',publication:'NOT_AUTHORIZED_NOT_RUN'},null,2)+'\n');
